import{_ as o,o as e,c as a,aa as n}from"./chunks/framework.BAs_AphD.js";const l="/buildary-help-preview/academy/img/editace-ukolu/03.webp",i="/buildary-help-preview/academy/img/editace-ukolu/05.webp",r="/buildary-help-preview/media/cs/tickets/vyjadreni.png",s="/buildary-help-preview/academy/img/editace-ukolu/09.webp",d="/buildary-help-preview/media/cs/tickets/historie.png",k="/buildary-help-preview/media/cs/tickets/navaz_zaznam_esd.png",u="/buildary-help-preview/media/cs/tickets/navaz_ukol.png",v="/buildary-help-preview/media/cs/tickets/ukol_volby.png",b=JSON.parse('{"title":"Řešit a schválit úkol","description":"","frontmatter":{"title":"Řešit a schválit úkol","wiki":"cs:tickets:task_edit"},"headers":[],"relativePath":"tickets/task_edit.md","filePath":"tickets/task_edit.md","lastUpdated":1794209661000}'),p={name:"tickets/task_edit.md"};function h(g,t,c,m,z,y){return e(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="resit-a-schvalit-ukol" tabindex="-1">Řešit a schválit úkol <a class="header-anchor" href="#resit-a-schvalit-ukol" aria-label="Permalink to &quot;Řešit a schválit úkol&quot;">​</a></h1><p>V detailu úkolu Řešitel mění stav úkolu a zapisuje vyjádření, Schvalovatel dokončený úkol zkontroluje a schválí, nebo zamítne. V detailu také najdete diskuzi, historii změn a související úkoly nebo záznamy v deníku.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/editace-ukolu">Změnit stav úkolu a odpovědět</a> v Akademii.</p><h2 id="otevrit-detail-ukolu" tabindex="-1">Otevřít detail úkolu <a class="header-anchor" href="#otevrit-detail-ukolu" aria-label="Permalink to &quot;Otevřít detail úkolu&quot;">​</a></h2><p>Detail úkolu otevřete kliknutím na jeho předmět – v Seznamu úkolů, v Kanbanu, na Dashboardu nebo v kalendáři. V seznamu můžete kliknout i na ikonu tužky, na výkresu a v mapě na <strong>Přejdi na detail úkolu</strong> u značky.</p><figure class="shot" style="--w:760px;"><img src="'+l+'" alt="Detail úkolu s rozbaleným výběrem stavu" loading="lazy"></figure><p>V záhlaví detailu vidíte:</p><ul><li>číslo úkolu a štítek s aktuálností podle plánovaného konce, například <strong>za týden</strong>,</li><li>Zadavatele úkolu (u jména je <strong>Autor</strong>),</li><li><strong>Související položky</strong> – odkazy na související úkoly a záznamy v deníku, viz <a href="#souvisejici-polozky">Související položky</a>,</li><li><strong>Diskuze a historie</strong>,</li><li>menu <strong>⋮</strong> s dalšími volbami.</li></ul><p>Formulář má stejná pole jako <a href="/buildary-help-preview/tickets/task_new">Zadat úkol</a>. Ve spodní liště jsou tlačítka:</p><table tabindex="0"><thead><tr><th>Tlačítko</th><th>Co udělá</th></tr></thead><tbody><tr><td><strong>Přejít na vyjádření</strong></td><td>posune stránku na část <strong>Vyjádření</strong></td></tr><tr><td><strong>Zrušit</strong></td><td>zahodí neuložené změny</td></tr><tr><td><strong>Uložit a zpět</strong></td><td>uloží změny a vrátí vás na stránku, odkud jste detail otevřeli</td></tr><tr><td><strong>Uložit</strong></td><td>uloží změny a nechá detail otevřený</td></tr></tbody></table><p>Která pole smíte měnit, závisí na vašem vztahu k úkolu (Zadavatel, Řešitel, Schvalovatel) a na vaší roli v projektovém týmu – viz <a href="/buildary-help-preview/tickets/permissions">Kdo co smí v úkolech</a>. Pole, která měnit nesmíte, jsou jen ke čtení.</p><h2 id="stavy-ukolu" tabindex="-1">Stavy úkolu <a class="header-anchor" href="#stavy-ukolu" aria-label="Permalink to &quot;Stavy úkolu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stav</th><th>Význam</th></tr></thead><tbody><tr><td><strong>Koncept</strong></td><td>Rozpracovaný úkol, který ještě není zadaný k řešení. Grafy na Dashboardu ho nezapočítávají.</td></tr><tr><td><strong>Nezahájeno</strong></td><td>Úkol je zadaný, řešení ještě nezačalo. Výchozí stav nového úkolu.</td></tr><tr><td><strong>Probíhá</strong></td><td>Řešitel na úkolu pracuje.</td></tr><tr><td><strong>Čeká se</strong></td><td>Řešení stojí, například na dodávku nebo na rozhodnutí.</td></tr><tr><td><strong>Odloženo</strong></td><td>Úkol se bude řešit později.</td></tr><tr><td><strong>Dokončeno</strong></td><td>Řešitel úkol splnil, čeká se na kontrolu.</td></tr><tr><td><strong>Schváleno</strong></td><td>Schvalovatel řešení zkontroloval a přijal.</td></tr><tr><td><strong>Zamítnuto</strong></td><td>Schvalovatel úkol zamítl.</td></tr></tbody></table><p>Stav změníte ve výběru <strong>Stav</strong> a uložíte. V Kanbanu ho změníte přetažením kartičky do jiného sloupce – viz <a href="/buildary-help-preview/tickets/task_grid#kanban">Seznam úkolů a filtry</a>.</p><h3 id="jak-ukol-prochazi-stavy" tabindex="-1">Jak úkol prochází stavy <a class="header-anchor" href="#jak-ukol-prochazi-stavy" aria-label="Permalink to &quot;Jak úkol prochází stavy&quot;">​</a></h3><ol><li>Zadavatel úkol zadá – obvykle ve stavu <strong>Nezahájeno</strong>. Úkol, který ještě není připravený, může nechat jako <strong>Koncept</strong>.</li><li>Řešitel přepne úkol na <strong>Probíhá</strong>.</li><li>Během řešení může Řešitel nastavit <strong>Čeká se</strong> nebo <strong>Odloženo</strong> a průběh popsat ve vyjádření.</li><li>Když je hotovo, Řešitel nastaví <strong>Dokončeno</strong>.</li><li>Schvalovatel řešení zkontroluje a nastaví <strong>Schváleno</strong>, nebo <strong>Zamítnuto</strong>.</li></ol><p><strong>Skutečný začátek</strong> a <strong>Skutečný konec</strong> doplňuje aplikace sama podle průběhu řešení, ručně je nezměníte. Stavy, které nastavit nesmíte, jsou ve výběru zašedlé.</p><p>O změnách úkolu dostávají upozornění Zadavatel, Řešitelé a Schvalovatelé – kromě toho, kdo změnu udělal. Viz <a href="/buildary-help-preview/tickets/notification">Upozornění na úkoly</a>. Změny stavu se zapisují také do diskuze úkolu.</p><h2 id="vyjadreni" tabindex="-1">Vyjádření <a class="header-anchor" href="#vyjadreni" aria-label="Permalink to &quot;Vyjádření&quot;">​</a></h2><p>Vyjádření je oficiální zápis k úkolu – co se udělalo, s fotografiemi nebo protokolem. Na rozdíl od diskuze je součástí exportu úkolu do PDF (kromě varianty <strong>Export PDF bez vyjádření</strong>, viz <a href="/buildary-help-preview/tickets/exports">Export úkolů</a>).</p><p>Na konci detailu klikněte na <strong>Přidat vyjádření</strong>. V okně napište text (nebo ho nadiktujte), přidejte přílohy tlačítkem <strong>Nahrát přílohu</strong> či přetažením a klikněte na <strong>Přidat</strong>. Vyjádření se uloží hned, nemusíte ukládat celý úkol.</p><figure class="shot" style="--w:760px;"><img src="'+i+'" alt="Okno Přidat vyjádření s polem pro text, tlačítkem Nahrát přílohu a tlačítky Zrušit a Přidat" loading="lazy"></figure><p>U každého vyjádření jsou tlačítka:</p><table tabindex="0"><thead><tr><th>Tlačítko</th><th>Co udělá</th></tr></thead><tbody><tr><td><strong>Reagovat</strong></td><td>Zapíše odpověď navázanou na toto vyjádření. <strong>Přidat vyjádření</strong> naopak založí nové vlákno.</td></tr><tr><td><strong>Upravit</strong></td><td>Změní text a přílohy vyjádření.</td></tr><tr><td><strong>Odstranit</strong></td><td>Smaže vyjádření.</td></tr></tbody></table><p>Upravit a odstranit smí vyjádření jen jeho autor, a to jen dokud na ně nikdo nereagoval – viz <a href="/buildary-help-preview/tickets/permissions#vyjadreni-a-prilohy">Kdo co smí v úkolech</a>.</p><figure class="shot" style="--w:600px;"><img src="'+r+'" alt="Vlákno vyjádření s přílohami, dvěma reakcemi a tlačítky Reagovat, Upravit a Odstranit" loading="lazy"></figure><h2 id="diskuze-a-historie" tabindex="-1">Diskuze a historie <a class="header-anchor" href="#diskuze-a-historie" aria-label="Permalink to &quot;Diskuze a historie&quot;">​</a></h2><p>Tlačítko <strong>Diskuze a historie</strong> v záhlaví otevře vpravo panel se dvěma záložkami.</p><div class="gallery"><figure class="shot"><img src="'+s+'" alt="Panel Diskuze k úkolu se změnami stavu a polem Vytvoření komentáře" loading="lazy"><figcaption>Diskuze</figcaption></figure><figure class="shot"><img src="'+d+'" alt="Panel Historie k úkolu se seznamem změn, autorem a časem" loading="lazy"><figcaption>Historie</figcaption></figure></div><ul><li><strong>Diskuze</strong> slouží k neformální domluvě nad úkolem. Komentář napište (nebo nadiktujte) do pole <strong>Vytvoření komentáře</strong> a klikněte na <strong>Uložit</strong>. V diskuzi se zobrazují i změny stavu úkolu. Diskuze není součástí žádného exportu.</li><li><strong>Historie</strong> zaznamenává všechny změny úkolu – kdo, kdy a co změnil. Starší záznamy načtete tlačítkem <strong>Načti celou historii</strong>.</li></ul><h2 id="prilohy" tabindex="-1">Přílohy <a class="header-anchor" href="#prilohy" aria-label="Permalink to &quot;Přílohy&quot;">​</a></h2><p>Přílohy úkolu jsou v části <strong>Přílohy</strong> detailu. Přidáte je stejně jako při zadání úkolu: přetažením nebo tlačítkem <strong>Nahrát přílohu</strong>. Přílohy úkolu přidává Zadavatel nebo Schvalovatel; fotografie a dokumenty k průběhu řešení přikládá každý účastník k vyjádření – viz <a href="#vyjadreni">Vyjádření</a>.</p><h2 id="souvisejici-polozky" tabindex="-1">Související položky <a class="header-anchor" href="#souvisejici-polozky" aria-label="Permalink to &quot;Související položky&quot;">​</a></h2><p>Má-li úkol vazbu na záznam v deníku nebo na jiné úkoly, zobrazí se u <strong>Související položky</strong> ikona s počtem:</p><div class="gallery"><figure class="shot"><img src="'+k+'" alt="Modrá ikona Související položky vlevo od Diskuze a historie s nápovědou Přejít na navazující záznam v deníku" loading="lazy"><figcaption>Záznam v deníku</figcaption></figure><figure class="shot"><img src="'+u+'" alt="Oranžová ikona Související položky vpravo od Diskuze a historie s nápovědou Úkol má související úkoly" loading="lazy"><figcaption>Související úkoly</figcaption></figure></div><ul><li><strong>Modrá ikona vlevo</strong> – úkol vznikl ze záznamu ve stavebním deníku. Kliknutím otevřete na nové záložce prohlížeče deník na dni, kde záznam je. Záznam v deníku má u sebe ikonu úkolu.</li><li><strong>Oranžová ikona vpravo</strong> – úkol má související úkoly. Kliknutím otevřete okno s jejich seznamem a z něj přejdete na detail souvisejícího úkolu.</li></ul><p>Jak související úkol založit, popisuje <a href="/buildary-help-preview/tickets/task_new#souvisejici-ukol">Zadat úkol</a>.</p><h2 id="dalsi-volby" tabindex="-1">Další volby <a class="header-anchor" href="#dalsi-volby" aria-label="Permalink to &quot;Další volby&quot;">​</a></h2><p>Menu <strong>⋮</strong> vpravo v záhlaví detailu nabízí:</p><table tabindex="0"><thead><tr><th>Volba</th><th>Co udělá</th></tr></thead><tbody><tr><td><strong>Vytvoření kopie úkolu</strong></td><td>otevře formulář Nový úkol s údaji tohoto úkolu</td></tr><tr><td><strong>Vytvořit související úkol</strong></td><td>otevře formulář Nový úkol s vazbou na tento úkol</td></tr><tr><td><strong>Stažení do PDF</strong></td><td>stáhne úkol jako PDF – viz <a href="/buildary-help-preview/tickets/exports">Export úkolů</a></td></tr><tr><td><strong>Smazat úkol</strong></td><td>smaže úkol</td></tr></tbody></table><figure class="shot" style="--w:560px;"><img src="'+v+'" alt="Rozbalené menu Další volby v detailu úkolu" loading="lazy"></figure><p>Zašedlou volbu nemůžete použít, protože k ní nemáte oprávnění.</p>',42)])])}const f=o(p,[["render",h]]);export{b as __pageData,f as default};
